package vn.edu.hunre.nhom11.carrental.payment.service;
import java.math.BigDecimal;import java.util.*;import java.util.regex.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.edu.hunre.nhom11.carrental.booking.service.BookingService;import vn.edu.hunre.nhom11.carrental.payment.domain.Payment;import vn.edu.hunre.nhom11.carrental.payment.repository.PaymentRepository;import vn.edu.hunre.nhom11.carrental.shared.exception.ApiException;
@Service public class PaymentService{private static final Pattern PAYMENT_CODE=Pattern.compile("CAR(\\d+)[^A-Z0-9]?([A-Z0-9]{6})(?![A-Z0-9])",Pattern.CASE_INSENSITIVE);private final PaymentRepository payments;private final BookingService bookings;private final String webhookApiKey;public PaymentService(PaymentRepository p,BookingService b,@Value("${app.sepay.webhook-api-key:}")String key){payments=p;bookings=b;webhookApiKey=key==null?"":key.trim();}
 @Transactional public Payment pay(String email,boolean admin,PaymentCommand r){var b=bookings.get(r.bookingId());if(!admin&&!b.getCustomer().getEmail().equalsIgnoreCase(email))throw new ApiException(HttpStatus.FORBIDDEN,"Bạn không thể thanh toán đơn này");if(b.getStatus().name().equals("CANCELLED")||b.getStatus().name().equals("COMPLETED"))throw new ApiException(HttpStatus.CONFLICT,"Đơn đã kết thúc, không thể thanh toán");if(r.amount()==null||r.amount().signum()<=0||b.getPaidAmount().add(r.amount()).compareTo(b.getTotalAmount())>0)throw new ApiException(HttpStatus.BAD_REQUEST,"Số tiền thanh toán không hợp lệ");if(blank(r.payerName())||blank(r.payerEmail())||blank(r.payerPhone())||r.method()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"Vui lòng điền đầy đủ thông tin thanh toán");if(r.method()==Payment.Method.BANK_TRANSFER)payments.findByBookingIdAndStatus(b.getId(),Payment.Status.PENDING).forEach(x->x.setStatus(Payment.Status.FAILED));Payment p=new Payment();p.setBooking(b);p.setAmount(r.amount());p.setMethod(r.method());p.setPayerName(r.payerName().trim());p.setPayerEmail(r.payerEmail().trim());p.setPayerPhone(r.payerPhone().trim());p.setBillingAddress(blank(r.billingAddress())?"Thanh toán chuyển khoản":r.billingAddress().trim());p.setProvider(blank(r.provider())?"VietinBank":r.provider().trim());p.setNote(r.note());p.setTransactionCode(r.method()==Payment.Method.BANK_TRANSFER?"CAR"+b.getId()+"-"+UUID.randomUUID().toString().substring(0,6).toUpperCase():"TX-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());if(r.method()==Payment.Method.BANK_TRANSFER)p.setStatus(Payment.Status.PENDING);else b.setPaidAmount(b.getPaidAmount().add(r.amount()));return payments.save(p);}
 @Transactional public Map<String,Object> receiveSePay(String authorization,SePayWebhook r){authenticateWebhook(authorization);if(r.id()==null||r.transferAmount()==null||r.transferAmount().signum()<=0||!"in".equalsIgnoreCase(r.transferType()))throw new ApiException(HttpStatus.BAD_REQUEST,"Webhook SePay không hợp lệ");String externalId=String.valueOf(r.id());if(payments.existsByExternalTransactionId(externalId))return Map.of("success",true,"message","Giao dịch đã được xử lý");String text=String.join(" ",Objects.toString(r.code(),""),Objects.toString(r.content(),""),Objects.toString(r.description(),"")).toUpperCase();Matcher matcher=PAYMENT_CODE.matcher(text);if(!matcher.find())throw new ApiException(HttpStatus.NOT_FOUND,"Không tìm thấy mã thanh toán trong giao dịch");String paymentCode="CAR"+matcher.group(1)+"-"+matcher.group(2);Payment p=payments.findByTransactionCodeIgnoreCase(paymentCode).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Mã thanh toán không tồn tại"));if(p.getStatus()==Payment.Status.SUCCESS)return Map.of("success",true,"message","Thanh toán đã được xác nhận");if(p.getStatus()!=Payment.Status.PENDING)throw new ApiException(HttpStatus.CONFLICT,"Mã thanh toán không còn hiệu lực");if(r.transferAmount().compareTo(p.getAmount())!=0)throw new ApiException(HttpStatus.BAD_REQUEST,"Số tiền chuyển khoản không khớp");var b=p.getBooking();if(b.getPaidAmount().add(p.getAmount()).compareTo(b.getTotalAmount())>0)throw new ApiException(HttpStatus.CONFLICT,"Số tiền vượt quá giá trị đơn");p.setStatus(Payment.Status.SUCCESS);p.setExternalTransactionId(externalId);p.setProvider(blank(r.gateway())?"SePay":r.gateway());p.setNote("SePay "+Objects.toString(r.referenceCode(),externalId));b.setPaidAmount(b.getPaidAmount().add(p.getAmount()));return Map.of("success",true,"message","Đã xác nhận thanh toán","paymentCode",p.getTransactionCode());}
 public Map<String,Object> webhookInfo(){return Map.of("endpointPath","/api/payments/sepay/webhook","authentication",webhookApiKey.isBlank()?"NONE":"API_KEY","pendingPayments",payments.countByStatus(Payment.Status.PENDING));}
 public Object byBooking(Long id,String email,boolean admin){var b=bookings.get(id);if(!admin&&!b.getCustomer().getEmail().equalsIgnoreCase(email))throw new ApiException(HttpStatus.FORBIDDEN,"Bạn không thể xem giao dịch của đơn này");return payments.findByBookingId(id);}public Object all(){return payments.findAll();}private void authenticateWebhook(String authorization){if(webhookApiKey.isBlank())return;if(!("Apikey "+webhookApiKey).equals(authorization))throw new ApiException(HttpStatus.UNAUTHORIZED,"Webhook API key không hợp lệ");}private boolean blank(String v){return v==null||v.isBlank();}public record PaymentCommand(Long bookingId,BigDecimal amount,Payment.Method method,String payerName,String payerEmail,String payerPhone,String billingAddress,String provider,String note){}public record SePayWebhook(Long id,String gateway,String transactionDate,String accountNumber,String subAccount,String code,String content,String transferType,String description,BigDecimal transferAmount,BigDecimal accumulated,String referenceCode){}
}
